}

const EXTENSION_LABELS: ExtensionLabelById = {
  'Autodesk.Viewing.MarkupsGui': 'Markups toolbar',
  'Autodesk.Viewing.MarkupsCore': 'Markups core',
  'Autodesk.BimWalk': 'BIM walk',
