                  'text-foreground before:bg-background before:shadow-xs hover:before:bg-background dark:before:bg-input/70',
              )}
              aria-pressed={selected}
              disabled={disabled}
              focusableWhenDisabled
              onClick={() => onChange(option.value)}
            >
              {option.label}
